// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Recorder rec;

    function setUp() public {
        c = new MultiplicatorX4();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1e24);
        address owner = c.Owner();
        vm.deal(owner, amount);
        vm.prank(owner);
        c.Command{value: amount}(address(rec), data);
        assertTrue(rec.lastValue() == amount && rec.calls() == 1, "callee must receive exactly msg.value");
    }
}

contract Recorder {
    uint256 public lastValue;
    uint256 public calls;

    fallback() external payable {
        lastValue = msg.value;
        calls++;
    }

    receive() external payable {
        lastValue = msg.value;
        calls++;
    }
}
